# NVIDIA technical blog on MLPerf Training v5.0, held against the v5.0 training times. python3 -I check_claims_nv_training_v50.py
import json,hashlib
FILES=['training_v50_times.json']; RAW={f:open(f,'rb').read() for f in FILES}
T=json.loads(RAW[FILES[0]]); s=str
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
def one(b,g,sub=None,acc=None,sysn=None):
    r=[x for x in T if x['benchmark']==b and x['gpus']==g and (sub is None or x['submitter']==sub) and (acc is None or acc in x['accelerator']) and (sysn is None or sysn in x['system'])]
    r=sorted(r,key=lambda x:x['official_style']); return r[0]['official_style'] if r else None
NT=[]
cells=[('llama31_405b',8192,'Hopper',20.8,'NVIDIA','H100'),('llama2_70b_lora',512,None,0.56,'NVIDIA','Blackwell'),('stable_diffusion',512,None,1.04,'NVIDIA','Blackwell'),('rgat',256,None,0.84,'NVIDIA','Blackwell'),('dlrm_dcnv2',64,None,0.7,'Supermicro','Blackwell'),('bert',512,None,0.3,'NVIDIA','Blackwell'),('retinanet',512,None,1.4,'NVIDIA','Blackwell')]
got=[(b,g,one(b,g,sub,acc),v) for b,g,_,v,sub,acc in cells]; dp=lambda v:len(s(v).split('.')[1]) if '.' in s(v) else 0
bad=[x for x in got if x[2] is None or abs(x[2]-x[3])>0.5*10**-dp(x[3])*1.0001]
NT.append(mk('NT1','Table 1 in the post, time to train in minutes on the NVIDIA platform for seven benchmarks','training_v50_times.json, entries at the scale of the cited submissions, official-style time','20.8, 0.56, 1.04, 0.84, 0.7, 0.3 and 1.4 minutes','; '.join(f'{b} on {g} GPUs {t:.2f}' for b,g,t,v in got),'CONSISTENT' if not bad else 'BELOW','The 20.8 minute Llama 3.1 405B value is the 8,192 GPU H100 entry. It is not a Blackwell result. The DLRM value is the Supermicro 64 GPU entry. Times are olympic averages of the logged runs, recomputed.'))
h=one('llama31_405b',512,'NVIDIA','H100'); bw=one('llama31_405b',512,None,'Blackwell'); bwn=one('llama31_405b',512,'NVIDIA','Blackwell'); bws=[x['submitter'] for x in T if x['benchmark']=='llama31_405b' and x['gpus']==512 and 'Blackwell' in x['accelerator'] and abs(x['official_style']-bw)<1e-9][0]
NT.append(mk('NT2','Table 2 in the post: Llama 3.1 405B on 512 GPUs, Hopper 269.12 min, Blackwell 121.09 min, speedup 2.2x','NVIDIA 512 GPU Llama 3.1 405B entries, H100 and Blackwell','269.12 and 121.09 minutes, 2.2x',f'H100 {h:.2f}, Blackwell {bw:.2f} (submitted by {bws}), ratio {h/bw:.2f}x; the NVIDIA own 512 GPU Blackwell entry is {bwn:.2f}','CONSISTENT' if round(h,2)==269.12 and round(h/bw,1)==2.2 and round(bw,2)==121.09 else 'BELOW','The 121.09 minute Blackwell value is the fastest 512 GPU Blackwell entry. NVIDIA own 512 GPU entry is 121.76, which gives 2.21x.'))
rows=[('Llama 2 70B LoRA',11.14,one('llama2_70b_lora',8,'NVIDIA','Blackwell',sysn='tyche'),27.93),('Stable Diffusion v2',12.86,one('stable_diffusion',8,'NVIDIA','Blackwell',sysn='tyche'),33.97),('GNN R-GAT',4.97,one('rgat',8,'NVIDIA','Blackwell',sysn='tyche'),11.18)]
NT.append(mk('NT3','Tables 3, 5 and 6 in the post: eight-GPU Blackwell times of 11.14 min (LoRA), 12.86 min (Stable Diffusion v2) and 4.97 min (GNN), against Hopper 27.93, 33.97 and 11.18 min, speedups 2.51x, 2.64x and 2.25x','NVIDIA eight-GPU Blackwell entries in the v5.0 training times; Hopper values are v4.1 entries','three Blackwell times and speedups','; '.join(f'{n}: Blackwell {b:.2f} (post {pb}), speedup on the post Hopper time {hp/b:.2f}x' for n,pb,b,hp in rows),'CONSISTENT' if all(round(b,2)==pb for n,pb,b,hp in rows) and [round(hp/b,2) for n,pb,b,hp in rows]==[2.51,2.64,2.25] else 'BELOW','The Hopper times are v4.1 entries that are not in the files, so the speedups rest on the post values for those. The Blackwell times match.'))
NT.append(mk('NT4','Table 4 in the post, June 2025 unverified results on H200 (21.84 min) and Blackwell (10.34 min) for Llama 2 70B LoRA','unverified results are not entries in the files','21.84 and 10.34 minutes unverified','no entry','CANNOT_TELL','The post marks the results as not verified by MLCommons.'))
best={}
for b in sorted({x['benchmark'] for x in T}):
    r=sorted([x for x in T if x['benchmark']==b],key=lambda x:x['official_style'])[0]; best[b]=(r['submitter'],r['gpus'],round(r['official_style'],2))
NT.append(mk('NT5','In this latest round of MLPerf Training, the NVIDIA platform delivered the fastest time to train across all seven benchmarks.','fastest time per benchmark in the v5.0 training times, any submitter, NVIDIA accelerators counted as the NVIDIA platform','fastest on all seven',str(best),'CONSISTENT' if all('NVIDIA' in [x for x in T if x['benchmark']==b and round(x['official_style'],2)==v[2]][0]['accelerator'] for b,v in best.items()) else 'BELOW','Fastest is read as the shortest time at any GPU count. Every benchmark has its fastest entry on NVIDIA accelerators.'))
big=[x for x in T if x['benchmark']=='llama31_405b' and 'Blackwell' in x['accelerator'] and x['gpus']>512]
NT.append(mk('NT6','the TP4 – CP2 – PP8 – DP39 layout emerges as optimal for the NVIDIA 2,496-GPU-scale Blackwell submission','Blackwell Llama 3.1 405B entries above 512 GPUs in the v5.0 training times','a 2,496 GPU Blackwell submission by NVIDIA','; '.join(f'{x["submitter"]} {x["gpus"]} GPUs {x["official_style"]:.2f} min' for x in sorted(big,key=lambda x:x['gpus'])),'BELOW','The 2,496 GPU Blackwell entry is submitted by IBM, CoreWeave and NVIDIA together. NVIDIA alone has no Blackwell entry above 512 GPUs. 64 GPUs per rack times 39 data parallel ranks is 2,496.'))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=NT),open('claims_nv_training_v50.json','w'),indent=1)
for c in NT: print(c['id'],c['outcome'],'|',c['stated'][:44],'|',c['delivered'][:330])
